# Творческие текстовые задачи для Codex (усилие medium). Результаты — в docs/gpt/<id>.md.
# Запуск: powershell -File scripts/gpt-tasks.ps1 [-Parallel 2] [-Only 01-monuments]
param([int]$Parallel = 2, [string[]]$Only = @())

$root = Split-Path -Parent $PSScriptRoot
$codex = Get-ChildItem "C:\Program Files\WindowsApps" -Directory -Filter "OpenAI.Codex_*" -ErrorAction SilentlyContinue |
    Sort-Object Name -Descending | ForEach-Object { Join-Path $_.FullName "app\resources\codex.exe" } |
    Where-Object { Test-Path $_ } | Select-Object -First 1

$common = @"
Ты помогаешь проектировать игру «Раствордд». Сначала прочитай AGENTS.md, docs/00-vision.md, docs/decisions.md, docs/ideas-log.md и нужные файлы в docs/design/.
Пиши по-русски, конкретно, с цифрами, без воды. Опирайся на опоры игры и принятые решения, не противоречь им.
Запиши результат ОДНИМ файлом в {OUT} (markdown). Не меняй никакие другие файлы, не пиши код игры.
"@

$tasks = [ordered]@{
    "01-monuments" = "Придумай 16–20 РТ (monuments) в духе Rust, но своих. Для каждого: название, размер (мелкий/средний/крупный, метры), где спавнится (биом, у воды, у дороги), уровень лута 1–3, охрана (тип NPC, число), особенность прохождения (карты доступа, рычаги, радиация, паркур, таймер), чем интересен для PvP (где кемпят, откуда заходят, где опасно выходить с лутом), планировка словами. Плюс 3–4 ивентовых РТ (аналоги карго и вертолёта). Учитывай вид 3/4 сверху, один этаж и туман войны."
    "02-items" = "Составь черновую базу предметов следующих этапов (то, чего ещё нет в game/src/Sim/Types.cs, но смотри его как образец): оружие по тирам (урон, скорострельность, магазин, перезарядка, разброс, дальность, шум), одежда и броня по слотам голова/торс/ноги/руки/ступни (защита от пуль, от холода, штраф к скорости), медицина, рейдовые средства (урон по уровням стен солома/дерево/камень/металл/МВК), постройки (стены, двери, замки, шкаф) с ценой крафта и уровнем верстака. Таблицы markdown. Баланс прогрессии как в Расте, без новомодного хайтека."
    "03-bot-scenarios" = "Составь 30 конкретных ситуаций для тестирования ботов-игроков и для каждой опиши, что сделает каждый архетип (роумер, фермер, РТ-шник, кемпер, рейдер, крыса, бомж) и почему, с учётом ставки (кит + груз) из docs/design/06-bots.md. Примеры: вышел с крупного РТ с фулл лутом и видит голого; слышит стрельбу в 150 м; объявлен закрытый ящик в 400 м; его база под рейдом, он в 600 м; ночь и 20% HP. В конце — числовые значения черт 0–1 для каждого архетипа и разброс."
    "04-traders" = "В Rust торговцы на аутпосте скучные. Предложи 8–10 механик, которые заменят торговлю и сделают реализацию лута рискованной и интересной (чёрный рынок с публичным сбросом, контракты директора, переработчик в спорных зонах и свои). Для каждой: как работает, какую опору игры усиливает, как в ней участвуют боты, риски для баланса. Выбери 2 лучшие и обоснуй."
    "05-stability" = "Базы строятся в один этаж на тайловой сетке. Нужна механика, которая не даёт бесконечно расширять базу и ставить тысячи дверей, но не душит строительство (стабильность вширь вместо высоты). Предложи 5–6 вариантов (радиус шкафа, прогрессивное содержание, опоры и пролёты и свои): формулы, плюсы и минусы, влияние на рейды, как это поймут боты, строящие по шаблонам. Порекомендуй комбинацию с конкретными числами."
    "06-lore" = "Придумай лор и сеттинг: что случилось с миром, почему остров, почему люди «просыпаются на пляже» и почему происходит вайп (внутриигровое объяснение), откуда РТ и охрана на них, кто такие боты-игроки в лоре. Мрачный трушный постапокалипсис без хайтека. Дай 3 варианта по 1–2 абзаца, выбери лучший и разверни: 10–15 мелких деталей мира (надписи, записки, названия мест), которые можно вставить в игру."
}

New-Item -ItemType Directory -Force (Join-Path $root "docs\gpt\_logs") | Out-Null
$running = @()
foreach ($id in $tasks.Keys) {
    if ($Only.Count -gt 0 -and $Only -notcontains $id) { continue }
    $out = "docs/gpt/$id.md"
    if (Test-Path (Join-Path $root $out)) { continue }
    while (($running | Where-Object { -not $_.HasExited }).Count -ge $Parallel) { Start-Sleep -Milliseconds 500 }
    $pf = Join-Path $root "docs\gpt\_logs\$id.prompt.txt"
    Set-Content -Path $pf -Value ($common.Replace("{OUT}", $out) + "`n`nЗадача: " + $tasks[$id]) -Encoding UTF8
    $log = Join-Path $root "docs\gpt\_logs\$id.log"
    $running += Start-Process -FilePath $codex -ArgumentList @("exec", "-C", "`"$root`"", "-s", "workspace-write", "-c", "model_reasoning_effort=`"medium`"", "-") `
        -RedirectStandardInput $pf -RedirectStandardOutput $log -RedirectStandardError "$log.err" -NoNewWindow -PassThru
    Write-Host "-> $id"
}
$running | ForEach-Object { $_.WaitForExit() }
foreach ($id in $tasks.Keys) { Write-Host ("{0,-18} {1}" -f $id, $(if (Test-Path (Join-Path $root "docs\gpt\$id.md")) { "ok" } else { "FAIL" })) }
